/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: videoKey, videoTrack, closeServer, readVideos
 *   Constants: ids
 *   Variables: harness, server, baseUrl
 * Tests
 *   - Videos lists only ready public Video MediaTracks newest first with safe DTOs
 *   - Videos pages continue from the issued cursor without repeating items
 *   - Videos rejects unknown parameters, malformed limits, and malformed cursors
 *   - Videos rechecks inherited visibility and source readiness on every continuation
 *   - inserting a newer Video never shifts or repeats an in-progress traversal
 *   - Videos bounds default and requested pages while excluding malformed persisted identities
 * @end-catalog */

import assert from 'node:assert/strict';
import { Server } from 'node:http';
import path from 'node:path';
import os from 'node:os';
import { after, before, test } from 'node:test';
import { ObjectId } from 'mongodb';

import { createApp } from '../../src/app';
import { getDb } from '../../src/infrastructure/database';
import {
    MongoReplicaSetHarness,
    startMongoReplicaSet
} from '../support/mongoReplicaSet';

let harness: MongoReplicaSetHarness | undefined;
let server: Server | undefined;
let baseUrl = '';

// ObjectIds increase with creation order, so the last created Video is the newest.
const ids = {
    artist: new ObjectId(),
    album: new ObjectId(),
    hiddenAlbum: new ObjectId(),
    oldestVideo: new ObjectId(),
    audio: new ObjectId(),
    pendingVideo: new ObjectId(),
    unpublishedVideo: new ObjectId(),
    hiddenAlbumVideo: new ObjectId(),
    privateVideo: new ObjectId(),
    wrongKindVideo: new ObjectId(),
    middleVideo: new ObjectId(),
    newestVideo: new ObjectId()
};

const videoKey = (trackId: ObjectId) => `video/${trackId}/${new ObjectId()}`;

const videoTrack = (id: ObjectId, title: string, overrides: Record<string, unknown> = {}) => ({
    _id: id,
    title,
    artistIds: [ids.artist.toString()],
    albumId: ids.album.toString(),
    duration: '04:14',
    coverArtUrl: `/${title}.jpg`,
    mediaType: 'video',
    uploadStatus: 'ready',
    s3Key: videoKey(id),
    contentType: 'video/mp4',
    uploadError: null,
    createdBy: 'private-owner',
    ...overrides
});

const closeServer = (target?: Server) => new Promise<void>((resolve, reject) => {
    if (!target) return resolve();
    target.close((error) => error ? reject(error) : resolve());
});

const readVideos = async (query = '') => {
    const response = await fetch(`${baseUrl}/api/listener/v1/videos${query}`);
    return { response, body: await response.json() as any };
};

before(async () => {
    harness = await startMongoReplicaSet('archtree-listener-videos-test');
    const db = getDb()!;
    await Promise.all([
        db.collection('artists').insertOne({
            _id: ids.artist,
            name: 'Theater Artist',
            bio: '',
            coverArtUrl: '/artist.jpg',
            albumIds: [ids.album.toString()],
            createdBy: 'private-owner'
        }),
        db.collection('albums').insertMany([
            {
                _id: ids.album,
                title: 'Theater Album',
                coverArtUrl: '/album.jpg',
                audioTrackIds: [],
                createdBy: 'private-owner'
            },
            {
                _id: ids.hiddenAlbum,
                title: 'Hidden Album',
                coverArtUrl: '/hidden.jpg',
                audioTrackIds: [],
                visibility: 'hidden',
                createdBy: 'private-owner'
            }
        ]),
        db.collection('audioTracks').insertMany([
            videoTrack(ids.oldestVideo, 'Oldest Video'),
            {
                _id: ids.audio,
                title: 'Plain Audio',
                artistIds: [ids.artist.toString()],
                albumId: ids.album.toString(),
                coverArtUrl: '',
                mediaType: 'audio',
                uploadStatus: 'ready',
                s3Key: ids.audio.toString(),
                createdBy: 'private-owner'
            },
            videoTrack(ids.pendingVideo, 'Pending Video', { uploadStatus: 'pending' }),
            videoTrack(ids.unpublishedVideo, 'Unpublished Video', { publicationStatus: 'pending' }),
            videoTrack(ids.hiddenAlbumVideo, 'Hidden Album Video', { albumId: ids.hiddenAlbum.toString() }),
            videoTrack(ids.privateVideo, 'Private Video', { visibility: 'private' }),
            videoTrack(ids.wrongKindVideo, 'Wrong Kind Video', { s3Key: `audio/${ids.wrongKindVideo}/${new ObjectId()}` }),
            videoTrack(ids.middleVideo, 'Middle Video', { albumId: null }),
            videoTrack(ids.newestVideo, 'Newest Video')
        ])
    ]);

    const app = createApp({
        listenerDistPath: path.join(os.tmpdir(), 'archtree-listener-videos-missing')
    });
    server = await new Promise<Server>((resolve) => {
        const listening = app.listen(0, '127.0.0.1', () => resolve(listening));
    });
    const address = server.address();
    assert.ok(address && typeof address !== 'string');
    baseUrl = `http://127.0.0.1:${address.port}`;
});

after(async () => {
    await closeServer(server);
    await harness?.stop();
});

test('Videos lists only ready public Video MediaTracks newest first with safe DTOs', async () => {
    const { response, body } = await readVideos();
    assert.equal(response.status, 200);
    assert.equal(response.headers.get('cache-control'), 'private, no-store');
    assert.deepEqual(body.items.map((item: any) => item.title), ['Newest Video', 'Middle Video', 'Oldest Video']);
    assert.equal(body.nextCursor, null);
    assert.deepEqual(body.items[0], {
        contentType: 'audioTrack',
        id: ids.newestVideo.toString(),
        title: 'Newest Video',
        artworkUrl: '/Newest Video.jpg',
        artistNames: ['Theater Artist'],
        albumId: ids.album.toString(),
        albumTitle: 'Theater Album',
        duration: '04:14',
        mediaType: 'video',
        streamUrl: `/content/mediaTrack/stream/${ids.newestVideo}`
    });
    assert.equal(body.items[1].albumId, null);
});

test('Videos pages continue from the issued cursor without repeating items', async () => {
    const first = await readVideos('?limit=2');
    assert.equal(first.response.status, 200);
    assert.deepEqual(first.body.items.map((item: any) => item.title), ['Newest Video', 'Middle Video']);
    assert.equal(first.body.nextCursor, ids.middleVideo.toString());

    const second = await readVideos(`?limit=2&cursor=${first.body.nextCursor}`);
    assert.equal(second.response.status, 200);
    assert.deepEqual(second.body.items.map((item: any) => item.title), ['Oldest Video']);
    assert.equal(second.body.nextCursor, null);
});

test('Videos rejects unknown parameters, malformed limits, and malformed cursors', async () => {
    for (const [query, code] of [
        ['?sort=title', 'invalid_video_query'],
        ['?limit=0', 'invalid_video_limit'],
        ['?limit=2.5', 'invalid_video_limit'],
        ['?limit=2&limit=3', 'invalid_video_limit'],
        ['?limit=10000', 'invalid_video_limit'],
        ['?cursor=', 'invalid_video_cursor'],
        ['?cursor=not-an-id', 'invalid_video_cursor'],
        [`?cursor=%20${ids.middleVideo}%20`, 'invalid_video_cursor'],
        [`?cursor=${ids.middleVideo}&cursor=${ids.oldestVideo}`, 'invalid_video_cursor'],
        ['?cursor[$gt]=a', 'invalid_video_cursor']
    ]) {
        const { response, body } = await readVideos(query);
        assert.equal(response.status, 400, query);
        assert.equal(body.code, code, query);
    }
    const capped = await readVideos('?limit=9999');
    assert.equal(capped.response.status, 200);
    assert.equal(capped.body.items.length, 3);
});

test('Videos rechecks inherited visibility and source readiness on every continuation', async (t) => {
    const db = getDb()!;
    t.after(async () => {
        await db.collection('albums').updateOne({ _id: ids.album }, { $unset: { visibility: '' } });
        await db.collection('audioTracks').updateOne({ _id: ids.middleVideo }, { $set: { uploadStatus: 'ready' } });
    });
    const first = await readVideos('?limit=1');
    assert.equal(first.body.nextCursor, ids.newestVideo.toString());

    await db.collection('albums').updateOne({ _id: ids.album }, { $set: { visibility: 'hidden' } });
    const hidden = await readVideos(`?limit=1&cursor=${first.body.nextCursor}`);
    assert.deepEqual(hidden.body.items.map((item: any) => item.title), ['Middle Video']);
    assert.equal(hidden.body.nextCursor, null);

    await db.collection('audioTracks').updateOne({ _id: ids.middleVideo }, { $set: { uploadStatus: 'deleting' } });
    const deleting = await readVideos(`?cursor=${first.body.nextCursor}`);
    assert.deepEqual(deleting.body, { items: [], nextCursor: null });
});

test('inserting a newer Video never shifts or repeats an in-progress traversal', async (t) => {
    const collection = getDb()!.collection('audioTracks');
    const first = await readVideos('?limit=2');
    const addedId = new ObjectId();
    t.after(async () => { await collection.deleteOne({ _id: addedId }); });
    await collection.insertOne(videoTrack(addedId, 'Added After First Page'));

    const next = await readVideos(`?limit=2&cursor=${first.body.nextCursor}`);
    assert.deepEqual(next.body.items.map((item: any) => item.title), ['Oldest Video']);
    assert.equal(next.body.nextCursor, null);
    const reloaded = await readVideos('?limit=1');
    assert.equal(reloaded.body.items[0].id, addedId.toString());
});

test('Videos bounds default and requested pages while excluding malformed persisted identities', async (t) => {
    const collection = getDb()!.collection('audioTracks');
    const extra = Array.from({ length: 52 }, (_, index) => videoTrack(new ObjectId(), `Bounded Video ${index}`, { albumId: null }));
    const malformedId = new ObjectId().toString();
    t.after(async () => {
        await collection.deleteMany({ _id: { $in: extra.map((track) => track._id) } });
        await collection.deleteOne({ _id: malformedId as any });
    });
    await collection.insertMany([...extra, {
        ...videoTrack(new ObjectId(), 'Malformed Identity', { albumId: null }),
        _id: malformedId as any,
        s3Key: `video/${malformedId}/${new ObjectId()}`
    }]);

    const normal = await readVideos();
    assert.equal(normal.body.items.length, 24);
    assert.ok(normal.body.nextCursor);
    const bounded = await readVideos('?limit=9999');
    assert.equal(bounded.body.items.length, 48);
    assert.ok(bounded.body.nextCursor);
    const rest = await readVideos(`?limit=48&cursor=${bounded.body.nextCursor}`);
    const combined = [...bounded.body.items, ...rest.body.items];
    assert.equal(combined.length, 55);
    assert.equal(new Set(combined.map((item: any) => item.id)).size, 55);
    assert.equal(combined.some((item: any) => item.title === 'Malformed Identity'), false);
});
